export const meta = {
  name: 'Warden I',
  rationale: 'You plant yourself on the right side and keep firing, so I slam that lane and make your safe window disappear.',
  version: 2,
};

export function init() {
  return {
    quietUntil: 0,
    targetCell: 0,
    refreshedAt: -1,
  };
}

export function decide(view, mem) {
  const boss = view.boss;
  const player = view.player;

  // Refresh the heat read once a second; the camper lives in a few stable cells.
  if (mem.refreshedAt < 0 || view.tick - mem.refreshedAt >= 60) {
    mem.targetCell = hottestRightCell(view.history.playerPosHeat);
    mem.refreshedAt = view.tick;
  }

  const cell = mem.targetCell | 0;
  const col = cell & 7;
  const row = (cell - col) >> 3;
  const cellW = view.arena.w / 8;
  const cellH = view.arena.h / 8;

  // Aim at the right-half heat, biased toward the upper-right lane and mid-right hold.
  let hotX = col * cellW + cellW * 0.5;
  let hotY = row * cellH + cellH * 0.5;
  if (hotX < view.arena.w * 0.5) hotX = view.arena.w * 0.75;
  if (hotY < 260 && hotX > 600) hotY = 260;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist2 = dx * dx + dy * dy;

  // One pressure source only: slam, and then a long quiet window.
  if (view.tick >= mem.quietUntil && boss.cooldowns.slam === 0) {
    const px = player.x;
    const py = player.y;
    const rightBias = px > view.arena.w * 0.5;
    const farEnough = dist2 > 160 * 160;

    // Slam the living lane, not the contact point.
    if (rightBias && farEnough) {
      mem.quietUntil = view.tick + 120;
      return { type: 'slam', x: clamp(px, 520, 780), y: clamp(py, 180, 620) };
    }
    if (!rightBias && dist2 > 220 * 220) {
      mem.quietUntil = view.tick + 120;
      return { type: 'slam', x: hotX, y: hotY };
    }
  }

  // Never punish contact; if the player is close, reopen space instead.
  if (dist2 < 150 * 150) {
    return moveAwayFromPlayer(boss.x, boss.y, player.x, player.y, view.arena.w, view.arena.h);
  }

  // Between attacks, hold the right lane and cut off the open edge.
  const anchorX = boss.x < 620 ? 620 : 700;
  const anchorY = clamp(player.y, 220, 580);
  return moveToward(boss.x, boss.y, anchorX, anchorY);
}

function hottestRightCell(heat) {
  let best = 23;
  let bestValue = -1;
  for (let i = 0; i < heat.length; i = i + 1) {
    const v = heat[i];
    if (typeof v !== 'number') continue;
    const col = i & 7;
    if (col < 4) continue;
    if (v > bestValue) {
      bestValue = v;
      best = i;
    }
  }
  return best;
}

function moveToward(bx, by, tx, ty) {
  const dx = tx - bx;
  const dy = ty - by;
  const m2 = dx * dx + dy * dy;
  if (!(m2 > 0)) return { type: 'idle' };
  const m = Math.sqrt(m2);
  return { type: 'move', dx: dx / m, dy: dy / m };
}

function moveAwayFromPlayer(bx, by, px, py, w, h) {
  let dx = bx - px;
  let dy = by - py;
  let m2 = dx * dx + dy * dy;
  if (!(m2 > 0)) {
    dx = 1;
    dy = 0;
    m2 = 1;
  }
  const m = Math.sqrt(m2);
  dx /= m;
  dy /= m;

  // Slight bias toward the center-left so the camper cannot keep the edge for free.
  if (bx > w * 0.5) dx -= 0.25;
  if (by < h * 0.5) dy += 0.08;
  if (by > h * 0.5) dy -= 0.08;

  const n2 = dx * dx + dy * dy;
  if (!(n2 > 0)) return { type: 'idle' };
  const n = Math.sqrt(n2);
  return { type: 'move', dx: dx / n, dy: dy / n };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

