export const meta = {
  name: 'Right Hand II',
  rationale: 'You hide on my right side, so I press that lane with slams, spawns, and a coin-flip burst when you step in.',
  version: 2,
};

export function init() {
  return {
    hot: 0,
    nextScan: 0,
    nextSpawn: 0,
    nextPress: 0,
    lastAction: 0,
    bias: 1,
  };
}

export function decide(view, mem) {
  const boss = view.boss;
  const t = view.tick;

  // Refresh the heat read every second; the camper lives where the map stays warm.
  if (t >= mem.nextScan || mem.hot < 0) {
    mem.hot = hottestCell(view.history.playerPosHeat);
    mem.nextScan = t + 60;
  }

  const target = preferredSpot(mem.hot, view.arena.w, view.arena.h);
  const px = view.player.x;
  const py = view.player.y;
  const bx = boss.x;
  const by = boss.y;

  const dx = px - bx;
  const dy = py - by;
  const dist2 = dx * dx + dy * dy;
  const dist = Math.sqrt(dist2);

  // Slow spawn cadence: two pressure sources, but no constant flood.
  if (boss.cooldowns.spawn === 0 && t >= mem.nextSpawn) {
    mem.nextSpawn = t + 420;
    mem.nextPress = t + 45;
    return { type: 'spawn', x: target.x, y: target.y };
  }

  // If they sit in the hot lane, slam that spot or step into it first.
  if (boss.cooldowns.slam === 0 && t >= mem.nextPress) {
    if (dist < 190) {
      mem.nextPress = t + 36;
      return { type: 'slam', x: target.x, y: target.y };
    }
    if (dist < 340 && rand() < 0.5) {
      mem.nextPress = t + 30;
      return { type: 'slam', x: target.x, y: target.y };
    }
  }

  // Contact punishment: half the time we answer with the full ring.
  if (boss.cooldowns.burst === 0 && t >= mem.nextPress) {
    if (dist < 130) {
      mem.nextPress = t + 28;
      return { type: 'burst', angle: Math.atan2(dy, dx), count: 8 };
    }
    if (dist < 260 && rand() < 0.5) {
      mem.nextPress = t + 28;
      return { type: 'burst', angle: Math.atan2(dy, dx), count: 5 };
    }
  }

  // Keep the body between the player and the open right edge.
  const guard = guardPoint(target, px, py, bx, by);
  const mx = guard.x - bx;
  const my = guard.y - by;
  const m2 = mx * mx + my * my;
  if (m2 > 16) {
    const inv = 1 / Math.sqrt(m2);
    return { type: 'move', dx: mx * inv, dy: my * inv };
  }

  return { type: 'idle' };
}

function preferredSpot(cell, w, h) {
  const cw = w / 8;
  const ch = h / 8;
  const col = cell % 8;
  const row = (cell - col) / 8;
  let x = col * cw + cw * 0.5;
  let y = row * ch + ch * 0.5;

  // Nudge toward the upper-right and mid-right lanes the player favored.
  if (x < w * 0.5) x = w * 0.78;
  if (y < h * 0.4) y = h * 0.28;
  if (y > h * 0.65) y = h * 0.68;

  return { x: clamp(x, 0, w), y: clamp(y, 0, h) };
}

function guardPoint(target, px, py, bx, by) {
  // Stay between the camper and the lane they prefer, but do not overcommit.
  const tx = target.x;
  const ty = target.y;
  const vx = tx - px;
  const vy = ty - py;
  const v2 = vx * vx + vy * vy;
  let ax = tx;
  let ay = ty;

  if (v2 > 1) {
    const inv = 1 / Math.sqrt(v2);
    ax = tx + vx * inv * 90;
    ay = ty + vy * inv * 90;
  }

  // Small bias to cut off their retreat toward the open right edge.
  if (px > 600) ax = ax - 40;
  if (py < 350) ay = ay + 10;

  // Blend a bit toward our current body so movement stays measured.
  ax = (ax + bx) * 0.5;
  ay = (ay + by) * 0.5;

  return { x: ax, y: ay };
}

function hottestCell(heat) {
  let best = 0;
  let bestValue = -1;
  for (let i = 0; i < heat.length; i = i + 1) {
    const v = heat[i];
    if (typeof v === 'number' && v > bestValue) {
      bestValue = v;
      best = i;
    }
  }
  return best;
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

