export const meta = {
  name: 'Warden III',
  rationale: 'You camped the right side and kept shooting through my windows, so I flood that lane with slams, rings, and bodies until your cover runs out.',
  version: 2,
};

export function init() {
  return {
    refreshedAt: -9999,
    hotA: 0,
    hotB: 0,
    hotC: 0,
    phase: 0,
  };
}

export function decide(view, mem) {
  // Refresh the pressure map on a slow beat; the camper tends to settle.
  if (view.tick - mem.refreshedAt >= 45 || mem.hotA < 0) {
    const top = topCells(view.history.playerPosHeat, 3);
    mem.hotA = top[0];
    mem.hotB = top[1];
    mem.hotC = top[2];
    mem.refreshedAt = view.tick;
    mem.phase = (mem.phase + 1) % 3;
  }

  const boss = view.boss;
  const player = view.player;

  const hot = chooseHot(mem.phase, mem.hotA, mem.hotB, mem.hotC, view.arena.w, view.arena.h);
  const hotX = hot.x;
  const hotY = hot.y;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = safeDist(dx, dy);

  // Three pressure sources: spawn, slam, and burst.
  if (boss.cooldowns.spawn === 0) {
    if (rand() < 0.9) return { type: 'spawn', x: hotX, y: hotY };
  }

  if (boss.cooldowns.slam === 0) {
    const rightBias = player.x > 500 ? 1 : 0;
    const readyToPin = player.y < 340 || player.y > 460 || rightBias;
    if (readyToPin && rand() < 0.72) {
      return { type: 'slam', x: hotX, y: hotY };
    }
  }

  if (boss.cooldowns.burst === 0 && dist < 260) {
    if (dist < 110 && rand() < 0.82) {
      return { type: 'burst', angle: angleOf(dx, dy), count: 8 };
    }
    if (rand() < 0.48) {
      return { type: 'burst', angle: angleOf(dx, dy), count: 5 };
    }
  }

  // Keep between the player and the open right edge, but do not fully seal every route.
  const anchorX = clamp(hotX - 80, 80, view.arena.w - 80);
