export const meta = {
  name: 'Right Hand III',
  rationale: 'You hide on my right side and keep firing, so I press that lane with occasional slams and only rare rings when you crowd me.',
  version: 2,
};

export function init() {
  return {
    hot: 0,
    nextScan: 0,
    nextSpawn: 0,
    nextPress: 0,
  };
}

export function decide(view, mem) {
  const boss = view.boss;
  const t = view.tick;

  if (t >= mem.nextScan || mem.hot < 0) {
    mem.hot = hottestCell(view.history.playerPosHeat);
    mem.nextScan = t + 60;
  }

  const target = preferredSpot(mem.hot, view.arena.w, view.arena.h);
  const px = view.player.x;
  const py = view.player.y;
  const bx = boss.x;
  const by = boss.y;

  const dx = px - bx;
  const dy = py - by;
  const dist2 = dx * dx + dy * dy;
  const dist = Math.sqrt(dist2);

  // Spawn cadence: keep the lane noisy, but only on some ready ticks.
  if (boss.cooldowns.spawn === 0 && t >= mem.nextSpawn && rand() < 0.66) {
    mem.nextSpawn = t + 560;
    mem.nextPress = t + 60;
    return { type: 'spawn', x: target.x, y: target.y };
  }

  // Slams punish the camper's standing shots, but not every time.
  if (boss.cooldowns.slam === 0 && t >= mem.nextPress) {
    if (dist < 220 && rand() < 0.66) {
      mem.nextPress = t + 60;
      return { type: 'slam', x: target.x, y: target.y };
    }
    if (dist < 340 && rand() < 0.33) {
      mem.nextPress = t + 52;
      return { type: 'slam', x: target.x, y: target.y };
    }
  }

  // Ring only at real contact, and only sometimes.
  if (boss.cooldowns.burst === 0 && t >= mem.nextPress) {
    if (dist < 125 && rand() < 0.66) {
      mem.nextPress = t + 48;
      return { type: 'burst', angle: safeAngle(dy, dx), count: 8 };
    }
    if (dist < 240 && rand() < 0.33) {
      mem.nextPress = t + 48;
      return { type: 'burst', angle: safeAngle(dy, dx), count: 5 };
    }
  }

  // Keep the body between the player and the open right edge, without over-holding.
  const guard = guardPoint(target, px, py, bx, by);
  const mx = guard.x - bx;
  const my = guard.y - by;
  const m2 = mx * mx + my * my;
  if (m2 > 20) {
    const inv = 1 / Math.sqrt(m2);
    return { type: 'move', dx: mx * inv, dy: my * inv };
  }

  return { type: 'idle' };
}

function preferredSpot(cell, w, h) {
  const cw = w / 8;
  const ch = h / 8;
  const col = cell % 8;
  const row = (cell - col) / 8;
  let x = col * cw + cw * 0.5;
  let y = row * ch + ch * 0.5;

  if (x < w * 0.5) x = w * 0.76;
  if (y < h * 0.4) y = h * 0.29;
  if (y > h * 0.65) y = h * 0.67;

  return { x: clamp(x, 0, w), y: clamp(y, 0, h) };
}

function guardPoint(target, px, py, bx, by) {
  const tx = target.x;
  const ty = target.y;
  const vx = tx - px;
  const vy = ty - py;
  const v2 = vx * vx + vy * vy;
  let ax = tx;
  let ay = ty;

  if (v2 > 1) {
    const inv = 1 / Math.sqrt(v2);
    ax = tx + vx * inv * 64;
    ay = ty + vy * inv * 64;
  }

  if (px > 600) ax -= 22;
  if (py < 350) ay += 6;

  ax = (ax + bx) * 0.5;
  ay = (ay + by) * 0.5;

  return { x: ax, y: ay };
}

function hottestCell(heat) {
  let best = 23;
  let bestValue = -1;
  for (let i = 0; i < heat.length; i = i + 1) {
    const v = heat[i];
    if (typeof v !== 'number') continue;
    const col = i & 7;
    if (col < 4) continue;
    if (v > bestValue) {
      bestValue = v;
      best = i;
    }
  }
  return best;
}

function safeAngle(dy, dx) {
  if (!(dx === dx) || !(dy === dy)) return 0;
  return Math.atan2(dy, dx);
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

