export const meta = {
  name: 'Warden I',
  rationale: 'You live on the right side and keep shooting, so I only sometimes slam that lane and keep my body in the way when you settle in.',
  version: 2,
};

export function init() {
  return {
    hot: 0,
    scanAt: 0,
    nextSlam: 0,
    nextSpawn: 0,
    nextBurst: 0,
  };
}

export function decide(view, mem) {
  const t = view.tick;
  const boss = view.boss;
  const px = view.player.x;
  const py = view.player.y;
  const bx = boss.x;
  const by = boss.y;

  if (t >= mem.scanAt || mem.hot < 0) {
    mem.hot = hottestRightCell(view.history.playerPosHeat);
    mem.scanAt = t + 60;
  }

  const target = preferredSpot(mem.hot, view.arena.w, view.arena.h);
  const dx = px - bx;
  const dy = py - by;
  const d2 = dx * dx + dy * dy;

  // Rare pressure source: spawn on the hot lane, but only some of the time.
  if (boss.cooldowns.spawn === 0 && t >= mem.nextSpawn && rand() < 0.34) {
    mem.nextSpawn = t + 560;
    mem.nextSlam = t + 48;
    return { type: 'spawn', x: target.x, y: target.y };
  }

  // Slam the right-half hold, but keep it intermittent so the panel can breathe.
  if (boss.cooldowns.slam === 0 && t >= mem.nextSlam) {
    if (px > view.arena.w * 0.5 && d2 > 140 * 140 && rand() < 0.34) {
      mem.nextSlam = t + 130;
      return { type: 'slam', x: clamp(target.x, 540, 780), y: clamp(target.y, 180, 620) };
    }
    if (d2 > 220 * 220 && rand() < 0.34) {
      mem.nextSlam = t + 130;
      return { type: 'slam', x: target.x, y: target.y };
    }
  }

  // Full ring only at true contact, and only sometimes.
  if (boss.cooldowns.burst === 0 && t >= mem.nextBurst) {
    if (d2 < 125 * 125 && rand() < 0.34) {
      mem.nextBurst = t + 55;
      return { type: 'burst', angle: safeAngle(dy, dx), count: 8 };
    }
    if (d2 < 240 * 240 && rand() < 0.34) {
      mem.nextBurst = t + 55;
      return { type: 'burst', angle: safeAngle(dy, dx), count: 5 };
    }
  }

  // Keep the body between the player and the open right edge, but do not over-hold.
  if (d2 < 155 * 155) {
    return moveAwayFromPlayer(bx, by, px, py, view.arena.w, view.arena.h);
  }

  const guard = guardPoint(target, px, py, bx, by);
  const mx = guard.x - bx;
  const my = guard.y - by;
  const m2 = mx * mx + my * my;
  if (m2 > 16) {
    const inv = 1 / Math.sqrt(m2);
    return { type: 'move', dx: mx * inv, dy: my * inv };
  }

  return { type: 'idle' };
}

function hottestRightCell(heat) {
  let best = 23;
  let bestValue = -1;
  for (let i = 0; i < heat.length; i = i + 1) {
    const v = heat[i];
    if (typeof v !== 'number') continue;
    if ((i & 7) < 4) continue;
    if (v > bestValue) {
      bestValue = v;
      best = i;
    }
  }
  return best;
}

function preferredSpot(cell, w, h) {
  const cw = w / 8;
  const ch = h / 8;
  const col = cell % 8;
  const row = (cell - col) / 8;
  let x = col * cw + cw * 0.5;
  let y = row * ch + ch * 0.5;

  if (x < w * 0.5) x = w * 0.75;
  if (y < 260 && x > 600) y = 260;
  if (y > 600) y = 560;

  return { x: clamp(x, 0, w), y: clamp(y, 0, h) };
}

function guardPoint(target, px, py, bx, by) {
  const vx = target.x - px;
  const vy = target.y - py;
  const v2 = vx * vx + vy * vy;
  let ax = target.x;
  let ay = target.y;

  if (v2 > 1) {
    const inv = 1 / Math.sqrt(v2);
    ax = target.x + vx * inv * 60;
    ay = target.y + vy * inv * 60;
  }

  if (px > 600) ax -= 24;
  if (py < 350) ay += 10;

  ax = (ax + bx) * 0.5;
  ay = (ay + by) * 0.5;

  return { x: ax, y: ay };
}

function moveAwayFromPlayer(bx, by, px, py, w, h) {
  let dx = bx - px;
  let dy = by - py;
  let m2 = dx * dx + dy * dy;
  if (!(m2 > 0)) {
    dx = 1;
    dy = 0;
    m2 = 1;
  }
  const m = Math.sqrt(m2);
  dx /= m;
  dy /= m;

  if (bx > w * 0.5) dx -= 0.22;
  if (by < h * 0.5) dy += 0.08;
  if (by > h * 0.5) dy -= 0.08;

  const n2 = dx * dx + dy * dy;
  if (!(n2 > 0)) return { type: 'idle' };
  const n = Math.sqrt(n2);
  return { type: 'move', dx: dx / n, dy: dy / n };
}

function safeAngle(dy, dx) {
  if (!(dx === dx) || !(dy === dy)) return 0;
  return Math.atan2(dy, dx);
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}
